    checkpoints: [choice("phishing-signal", 125, "Which detail is the strongest reason to stop before clicking?", ["The message uses a logo", "Unexpected urgency plus a mismatched link destination", "It has complete sentences", "It arrived by email"], 1, "Branding can be copied. Unexpected pressure and a destination unrelated to the real service are high-value warning signals."), choice("password-manager", 260, "How should you manage strong unique passwords across many accounts?", ["Reuse one complicated password", "Use a reputable password manager and MFA", "Store them in a public document", "Share them with friends"], 1, "Unique credentials stop one breach from unlocking everything; a password manager makes uniqueness practical."), choice("compromise-response", 385, "You approved an MFA prompt you did not initiate. What should you do?", ["Wait a week", "Use a trusted device to change the password, revoke sessions, and report it", "Approve more prompts", "Post the code publicly"], 1, "An unrequested prompt can signal stolen credentials. Act quickly through a known-safe route and review recovery settings.")],
